// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *BOMComponent) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, BOMComponentTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (parent_item_no, line_no)`,
		fmt.Sprintf("%s$BOM_Component$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (type, no)`,
		fmt.Sprintf("%s$BOM_Component$type_no", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index type_no: %w", err)
	}
	var keys []sift.Key
	for _, spec := range bOMComponentSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, BOMComponentTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, BOMComponentTableName, keys)
}

